<script setup>import {ref} from 'vue';import {useApp} from '../stores/app';import {useRouter} from 'vue-router';import PageTitle from '../components/PageTitle.vue';const s=useApp(),router=useRouter(),username=ref(''),password=ref(''),error=ref('');function submit(){try{s.login(username.value,password.value);router.push({admin:'/dashboard',cashier:'/pos',barista:'/orders',customer:'/catalog'}[s.user.role])}catch(e){error.value=e.message}}</script><template><PageTitle title="Selamat datang." subtitle="Masuk untuk memulai aktivitas outlet."/><form class="card narrow" @submit.prevent="submit"><label>Username<input v-model="username" required></label><label>Kata sandi<input type="password" v-model="password" required></label><p class="error" v-if="error">{{error}}</p><button>Masuk</button><small>Akun simulasi: nopal, raka, dinda, farel. Sandi: demo123</small></form></template>
